<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionTemplateVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;

trait TemplateVersionTemplateAccessor
{
    private TemplateVersionTemplateVO $_template;
    public function getTemplate(): TemplateRef
    {
        return $this->_template->value();
    }
    public function template(): TemplateVersionTemplateVO
    {
        return $this->_template;
    }
    public function isTemplateChanged(?self $original = null): bool
    {
        return !$this->_template->equals($original?->_template);
    }
    public function withTemplate(TemplateVersionTemplateVO|TemplateRef $template): self
    {
        $copy = clone $this;
        $copy->_template = TemplateVersionTemplateVO::from($template);
        return $copy;
    }
}
